<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {football,matchTime,type Fixture,type Evidence} from '../centre/football'
const live=ref<Fixture[]>([]),fixture=ref(''),record=ref<Evidence>(),question=ref('goal'),error=ref(''),busy=ref(false)
const life=new AbortController();let request:AbortController|undefined
async function load(){request?.abort();const current=new AbortController();request=current;busy.value=true;record.value=undefined;error.value=''
try{const value=await football<Evidence>('fixtures/'+encodeURIComponent(fixture.value)+'/ai-context',current.signal);if(current===request&&value.data.fixture.id===fixture.value&&value.data.source_is_synthetic)record.value=value.data}catch{if(current===request)error.value='Evidence unavailable for this fixture.'}finally{if(current===request)busy.value=false}}
async function discover(){try{const result=await football<Fixture[]>('live',life.signal);live.value=result.data;fixture.value=result.data[0]?.id??'';if(fixture.value)await load()}catch{if(!life.signal.aborted)error.value='No connection to the simulated evidence feed.'}}
const references=computed(()=>(record.value?.events_so_far??[]).filter(e=>e.type===question.value)),questions=[['goal','Who scored?'],['yellow_card','Who was booked?'],['substitution','Who was substituted?']]
onMounted(discover);onBeforeUnmount(()=>{life.abort();request?.abort();request=undefined})
</script>
<template><section class="motion-desk"><p class="eyebrow">EVIDENCE STUDIO / SIMULATED DEMO</p><h3>Go to the source.</h3><div class="centre-controls"><label>Match context<select v-model="fixture" @change="load"><option v-for="f in live" :key="f.id" :value="f.id">{{ f.home_team_name }} v {{ f.away_team_name }}</option></select></label><label>Evidence question<select v-model="question"><option v-for="q in questions" :key="q[0]" :value="q[0]">{{ q[1] }}</option></select></label></div><p v-if="busy" role="status">Reading fixture evidence…</p><p v-else-if="error">{{ error }} <button class="text-link" @click="discover">Retry</button></p><template v-else-if="record"><p>Snapshot at {{ matchTime(record.fixture.clock_seconds) }}. {{ references.length }} matching incident(s) in the available event log.</p><ol class="incident-list"><li v-for="e in references" :key="e.id"><RouterLink class="text-link" :to="{path:'/matches',query:{fixture:fixture,at:e.clock_seconds}}">{{ matchTime(e.clock_seconds) }} · {{ e.type.replaceAll('_',' ') }} ↗</RouterLink> {{ e.player_id }}</li></ol></template><p>Deterministic evidence lookup. An event log cannot establish tactical intent.</p></section></template>
